$pageTitle='Dashboard';$activePage='dashboard.php';require __DIR__.'/../includes/admin_layout.php';
$counts=[
 'employees'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE pathway='employee_va'")->fetchColumn(),
